def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    cycle = red_duration + green_duration
    result = []
    for a in arrivals:
        r = a % cycle
        if r < red_duration:
            result.append(a)
        else:
            result.append(a + (cycle - r))
    return result

def undo_redo_state(commands):
    doc = []
    redo_stack = []
    for command in commands:
        op = command[0]
        if op == 'do':
            _, value = command
            doc.append(value)
            redo_stack = []
        elif op == 'undo':
            if doc:
                redo_stack.append(doc.pop())
        elif op == 'redo':
            if redo_stack:
                doc.append(redo_stack.pop())
    return doc

def vote_gate_state(events, threshold):
    net = 0
    state = 'CLOSED'
    for event in events:
        if state == 'OPEN':
            break
        if event == 'yes':
            net += 1
        elif event == 'no':
            net -= 1
        if net >= threshold:
            state = 'OPEN'
    return state

def coffee_machine_credit(events, prices, stock):
    stock = dict(stock)
    credit = 0
    dispensed = 0
    for op, value in events:
        if op == 'insert':
            credit += value
        elif op == 'select':
            drink = value
            if stock.get(drink, 0) > 0 and credit >= prices[drink]:
                credit -= prices[drink]
                stock[drink] -= 1
                dispensed += 1
    return (credit, stock, dispensed)

def bank_balance_with_fee(events, fee):
    balance = 0
    for op, amount in events:
        if op == 'deposit':
            balance += amount
        elif op == 'withdraw':
            if balance >= amount + fee:
                balance -= (amount + fee)
    return balance

def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    req_set = set(requests)
    result = []
    target = 1 if direction == -1 else top_floor
    floor = start_floor
    while floor != target:
        floor += direction
        if floor in req_set:
            result.append(floor)
    return result

def grid_bot_fuel(commands, fuel):
    deltas = {'N': (0, 1), 'S': (0, -1), 'E': (1, 0), 'W': (-1, 0)}
    x, y = 0, 0
    remaining = fuel
    for c in commands:
        if remaining <= 0:
            break
        dx, dy = deltas[c]
        x += dx
        y += dy
        remaining -= 1
    return ((x, y), remaining)

def register_finalized_totals(events):
    current = []
    totals = []
    for event in events:
        op = event[0]
        if op == 'scan':
            _, price = event
            current.append(price)
        elif op == 'void':
            if current:
                current.pop()
        elif op == 'pay':
            totals.append(sum(current))
            current = []
    return totals

def light_switch_group(n, events):
    lights = [False] * n
    for event in events:
        op = event[0]
        if op == 'toggle':
            _, i = event
            lights[i] = not lights[i]
        elif op == 'toggle_all':
            lights = [not v for v in lights]
        elif op == 'reset':
            lights = [False] * n
    return lights

def queue_with_capacity_serve(events, capacity):
    queue = []
    for event in events:
        op = event[0]
        if op == 'arrive':
            _, person_id = event
            queue.append(person_id)
        elif op == 'serve':
            queue = queue[capacity:]
    return queue

def loan_debt_balance(events):
    debt = 0
    for op, amount in events:
        if op == 'borrow':
            debt += amount
        elif op == 'repay':
            debt = max(0, debt - amount)
    return debt

def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def light_state(t, durations):
        red, green, yellow = durations
        cycle = red + green + yellow
        r = t % cycle
        if r < red:
            return 'RED'
        elif r < red + green:
            return 'GREEN'
        else:
            return 'YELLOW'

    count = 0
    for t in range(n_ticks):
        if light_state(t, durations_a) == 'GREEN' and light_state(t, durations_b) == 'GREEN':
            count += 1
    return count
